"""Original developmental and personal-history fields. Documentation only; no inference."""
from modules.questionnaires import digest
DOMAINS=[{'key': 'developmental', 'label': 'Developmental History'}, {'key': 'emotional', 'label': 'Emotional–Behavioral History'}, {'key': 'socioeconomic', 'label': 'Socioeconomic History'}, {'key': 'sexual', 'label': 'Sexual History'}]
GROUPS=[{'key': 'birth', 'domain': 'developmental', 'label': 'Pregnancy / Birth / Early Development', 'choices': ['Full-term birth reported', 'Premature birth', 'Low birth weight', 'Pregnancy / birth complications reported', 'Prenatal substance exposure reported', 'Significant illness in infancy', 'Early hospitalization', 'Other early developmental information', 'History unknown', 'Not applicable', 'Prefers not to discuss']}, {'key': 'milestones', 'domain': 'developmental', 'label': 'Developmental Milestones', 'choices': ['Milestones achieved as expected', 'Speech / language delay', 'Motor development delay', 'Social development concerns', 'Toileting delay / difficulty', 'Early intervention services', 'Developmental evaluation', 'Ongoing developmental support needs', 'Other milestone history', 'History unknown', 'Not applicable', 'Prefers not to discuss']}, {'key': 'learning', 'domain': 'developmental', 'label': 'School / Learning History', 'choices': ['School adjustment without reported difficulty', 'Reading / writing difficulty', 'Mathematics difficulty', 'Attention / organization difficulty', 'Special education / learning accommodations', 'Speech / language services', 'Repeated grade(s)', 'Frequent school changes', 'Frequent absences', 'Bullying / peer difficulties', 'Left school before completion', 'Other learning history', 'History unknown', 'Not applicable', 'Prefers not to discuss']}, {'key': 'emotional_history', 'domain': 'emotional', 'label': 'Emotional History Over Time', 'choices': ['Childhood anxiety / fears', 'Periods of depressed mood', 'Mood changes / emotional reactivity', 'Grief / significant loss', 'Traumatic experiences reported', 'Separation / attachment difficulties', 'Difficulty identifying / expressing emotions', 'Emotional numbness / detachment', 'Prior counseling / skills-based treatment reported', 'Other emotional history', 'History unknown', 'Not applicable', 'Prefers not to discuss']}, {'key': 'behavior', 'domain': 'emotional', 'label': 'Behavioral History', 'choices': ['Anger / irritability / temper outbursts', 'Aggressive behavior', 'Oppositional behavior', 'Impulsive behavior', 'Risk-taking behavior', 'School discipline problems', 'Running away / leaving home without permission', 'Self-harm history reported', 'Suicidal thoughts / behavior history reported', 'Difficulty following rules / routines', 'Other behavioral history', 'History unknown', 'Not applicable', 'Prefers not to discuss']}, {'key': 'coping', 'domain': 'emotional', 'label': 'Coping / Emotional Regulation', 'choices': ['Can identify emotions', 'Uses calming / relaxation strategies', 'Uses hobbies / physical activity', 'Uses spiritual / cultural supports', 'Difficulty tolerating distress', 'Avoidance of upsetting situations', 'Other coping history', 'History unknown', 'Not applicable', 'Prefers not to discuss']}, {'key': 'education_work', 'domain': 'socioeconomic', 'label': 'Education / Work / Income Context', 'choices': ['Currently in school / training', 'Completed high school / equivalent', 'College / vocational education', 'Employed full-time', 'Employed part-time', 'Self-employed', 'Unemployed / seeking work', 'Retired', 'Homemaking / caregiving responsibilities', 'Receives disability-related support', 'Job instability / frequent job changes', 'Workplace stress / conflict', 'Other education / work information', 'History unknown', 'Not applicable', 'Prefers not to discuss']}, {'key': 'housing_finances', 'domain': 'socioeconomic', 'label': 'Housing / Financial Circumstances', 'choices': ['Stable housing', 'Lives independently', 'Lives with family / others', 'Temporary / transitional housing', 'Housing insecurity / homelessness', 'Financial stability reported', 'Financial strain / debt / difficulty meeting basic expenses', 'Food insecurity', 'Dependent on others for financial support', 'Transportation difficulties', 'Other housing / financial information', 'History unknown', 'Not applicable', 'Prefers not to discuss']}, {'key': 'social_context', 'domain': 'socioeconomic', 'label': 'Social / Community Circumstances', 'choices': ['Supportive relationships / social support', 'Limited social support', 'Social withdrawal / isolation', 'Community involvement', 'Military service history', 'Legal / court involvement affecting daily life', 'Discrimination / marginalization reported', 'Cultural / language barriers reported', 'Significant recent life transition', 'Other social circumstances', 'History unknown', 'Not applicable', 'Prefers not to discuss']}, {'key': 'orientation', 'domain': 'sexual', 'label': 'Sexual Orientation — Patient Self-Description', 'choices': ['Heterosexual / straight', 'Gay', 'Lesbian', 'Bisexual', 'Pansexual', 'Asexual', 'Queer', 'Questioning / exploring', 'Another self-description', 'History unknown', 'Not applicable', 'Prefers not to discuss']}, {'key': 'sexual_relationships', 'domain': 'sexual', 'label': 'Relationship / Sexual History', 'choices': ['Current intimate relationship', 'Past intimate relationship(s)', 'No prior intimate relationship reported', 'Currently sexually active — patient reported', 'Previously sexually active — patient reported', 'No sexual activity reported', 'Relationship satisfaction reported', 'Relationship conflict / distress', 'Concerns about boundaries / consent', 'Other relationship / sexual history', 'History unknown', 'Not applicable', 'Prefers not to discuss']}, {'key': 'sexual_health', 'domain': 'sexual', 'label': 'Sexual Health / Experiences / Concerns', 'choices': ['No sexual-health concerns reported', 'Sexual functioning / interest concerns', 'Pain / discomfort associated with sexual activity reported', 'Medication-related sexual concerns reported', 'Sexually transmitted infection history reported', 'Contraception / family-planning concerns', 'Unwanted sexual experiences / coercion / abuse / assault reported', 'Other sexual-health concern', 'History unknown', 'Not applicable', 'Prefers not to discuss']}]
NOTES={'developmental_notes': 'Developmental Details / Dates / Other Information', 'emotional_notes': 'Emotional–Behavioral Details / Timing / Other Information', 'socioeconomic_notes': 'Socioeconomic Details / Changes Over Time', 'sexual_notes': 'Sexual History Details — Optional', 'source_notes': 'Source of History / Other Information'}
EXCLUSIVE=['History unknown', 'Not applicable', 'Prefers not to discuss','No sexual-health concerns reported']
DEFINITION={'version':'2.0.0','consolidation_version':'1','domains':DOMAINS,'groups':GROUPS,'notes':NOTES,'exclusive':EXCLUSIVE}
def validate(data):
    selections=data.get('selections')
    notes=data.get('notes',{})
    if not isinstance(selections,dict) or not isinstance(notes,dict):raise ValueError('Invalid developmental/personal history form.')
    if set(selections)-{g['key'] for g in GROUPS} or set(notes)-set(NOTES):raise ValueError('Unknown developmental/personal history field.')
    clean={}
    for group in GROUPS:
        values=selections.get(group['key'],[])
        if not isinstance(values,list) or any(not isinstance(v,str) or v not in group['choices'] for v in values) or len(values)!=len(set(values)):raise ValueError('Choose supported developmental/personal history items without duplicates.')
        if any(v in EXCLUSIVE for v in values) and len(values)>1:raise ValueError('None reported / History unknown cannot be combined with other choices in the same section.')
        clean[group['key']]=values
    text={}
    for key in NOTES:
        value=notes.get(key,'')
        if not isinstance(value,str) or len(value)>4000:raise ValueError('History details must be at most 4000 characters per field.')
        text[key]=value.strip()
    return {'schema':'biopsychosocial-developmental-personal/1','selections':clean,'notes':text,'definition':DEFINITION,'definition_hash':digest(DEFINITION),'synthetic':True}
